-- BOLOS & GESTÃO v2.0 — execute em projeto Supabase NOVO.
-- Frontend deve usar somente publishable/anon key. Nunca exponha service_role.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz default now());
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),name text not null,document text,phone text,email text,notes text,created_at timestamptz default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),name text not null,phone text,email text,notes text,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),name text not null,product_type text not null check(product_type in('ingredient','packaging','cake')),barcode text,unit text not null default 'un',stock_quantity numeric(14,3) not null default 0 check(stock_quantity>=0),minimum_stock numeric(14,3) not null default 0,average_cost numeric(14,4) not null default 0,sale_price numeric(14,2) not null default 0,active boolean not null default true,created_at timestamptz default now(),updated_at timestamptz default now(),unique(owner_id,barcode));
create table if not exists public.purchases(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),supplier_id uuid references public.suppliers(id),purchase_date date default current_date,total_amount numeric(14,2) default 0,payment_status text default 'paid' check(payment_status in('paid','pending','partial')),notes text,created_at timestamptz default now());
create table if not exists public.purchase_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),purchase_id uuid not null references public.purchases(id) on delete cascade,product_id uuid not null references public.products(id),quantity numeric(14,3) not null,unit_cost numeric(14,4) not null,line_total numeric(14,2) not null);
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),product_id uuid not null references public.products(id),movement_type text not null,quantity_delta numeric(14,3) not null,unit_cost numeric(14,4) default 0,reference_type text,reference_id uuid,notes text,created_at timestamptz default now());
create table if not exists public.price_history(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),product_id uuid not null references public.products(id),supplier_id uuid references public.suppliers(id),recorded_at timestamptz default now(),purchase_unit_cost numeric(14,4) not null,source text default 'purchase');
create table if not exists public.recipes(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),finished_product_id uuid not null references public.products(id),name text not null,yield_quantity numeric(14,3) not null check(yield_quantity>0),preparation_notes text,active boolean default true,created_at timestamptz default now());
create table if not exists public.recipe_ingredients(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),recipe_id uuid not null references public.recipes(id) on delete cascade,ingredient_product_id uuid not null references public.products(id),quantity numeric(14,3) not null,unit text not null);
create table if not exists public.productions(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),recipe_id uuid references public.recipes(id),produced_product_id uuid not null references public.products(id),produced_quantity numeric(14,3) not null,production_date timestamptz default now(),total_cost numeric(14,2) default 0,unit_cost numeric(14,4) default 0,notes text);
create table if not exists public.production_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),production_id uuid not null references public.productions(id) on delete cascade,ingredient_product_id uuid not null references public.products(id),quantity_used numeric(14,3) not null,unit_cost_snapshot numeric(14,4) not null,line_cost numeric(14,2) not null);
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),customer_id uuid references public.customers(id),sale_number bigint generated by default as identity,sold_at timestamptz default now(),subtotal numeric(14,2) not null,discount numeric(14,2) default 0,total numeric(14,2) not null,payment_method text not null check(payment_method in('cash','pix','debit','credit','on_account')),payment_status text default 'paid',notes text,created_at timestamptz default now(),unique(owner_id,sale_number));
create table if not exists public.sale_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),sale_id uuid not null references public.sales(id) on delete cascade,product_id uuid not null references public.products(id),product_name_snapshot text not null,quantity numeric(14,3) not null,unit_price numeric(14,2) not null,unit_cost_snapshot numeric(14,4) not null,line_total numeric(14,2) not null);
create table if not exists public.cash_sessions(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),opened_at timestamptz default now(),opening_amount numeric(14,2) default 0,closed_at timestamptz,closing_expected numeric(14,2),closing_counted numeric(14,2));
create table if not exists public.cash_movements(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),cash_session_id uuid references public.cash_sessions(id),movement_type text not null,amount numeric(14,2) not null,description text not null,reference_type text,reference_id uuid,created_at timestamptz default now());
create table if not exists public.accounts_payable(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),description text not null,supplier_id uuid references public.suppliers(id),due_date date,amount numeric(14,2) not null,paid_amount numeric(14,2) default 0,status text default 'pending' check(status in('pending','partial','paid','cancelled')),created_at timestamptz default now());
create table if not exists public.accounts_receivable(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),description text not null,customer_id uuid references public.customers(id),sale_id uuid references public.sales(id),due_date date,amount numeric(14,2) not null,received_amount numeric(14,2) default 0,status text default 'pending',created_at timestamptz default now());
create table if not exists public.goals(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),name text not null,goal_type text not null check(goal_type in('revenue','profit','units_sold','production','new_customers')),target_value numeric(14,2) not null,starts_on date not null,ends_on date not null,active boolean default true);
-- RLS: isolamento por proprietário autenticado.
do $$ declare t text; begin foreach t in array array['suppliers','customers','products','purchases','purchase_items','stock_movements','price_history','recipes','recipe_ingredients','productions','production_items','sales','sale_items','cash_sessions','cash_movements','accounts_payable','accounts_receivable','goals'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists owner_all on public.%I',t); execute format('create policy owner_all on public.%I for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid())',t); end loop; alter table public.profiles enable row level security; drop policy if exists profile_self on public.profiles; create policy profile_self on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid()); end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email)) on conflict(id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Compra: atualiza estoque, custo médio ponderado, histórico e contas a pagar em uma transação.
create or replace function public.register_purchase(p_supplier_id uuid,p_product_id uuid,p_quantity numeric,p_unit_cost numeric,p_payment_status text default 'paid',p_notes text default null) returns uuid language plpgsql security invoker as $$ declare o uuid:=auth.uid(); pid uuid; q numeric; c numeric; begin if o is null then raise exception 'Autenticação necessária'; end if; if p_quantity<=0 or p_unit_cost<0 then raise exception 'Quantidade/custo inválido'; end if; select stock_quantity,average_cost into q,c from products where id=p_product_id and owner_id=o for update; if not found then raise exception 'Produto não encontrado'; end if; insert into purchases(owner_id,supplier_id,total_amount,payment_status,notes) values(o,p_supplier_id,p_quantity*p_unit_cost,p_payment_status,p_notes) returning id into pid; insert into purchase_items(owner_id,purchase_id,product_id,quantity,unit_cost,line_total) values(o,pid,p_product_id,p_quantity,p_unit_cost,round(p_quantity*p_unit_cost,2)); update products set stock_quantity=q+p_quantity,average_cost=((q*c)+(p_quantity*p_unit_cost))/(q+p_quantity) where id=p_product_id; insert into stock_movements(owner_id,product_id,movement_type,quantity_delta,unit_cost,reference_type,reference_id) values(o,p_product_id,'purchase',p_quantity,p_unit_cost,'purchase',pid); insert into price_history(owner_id,product_id,supplier_id,purchase_unit_cost) values(o,p_product_id,p_supplier_id,p_unit_cost); if p_payment_status<>'paid' then insert into accounts_payable(owner_id,description,supplier_id,due_date,amount,status) values(o,'Compra de estoque',p_supplier_id,current_date,p_quantity*p_unit_cost,'pending'); end if; return pid; end $$;
-- Produção: receita deve usar a mesma unidade cadastrada no ingrediente/estoque. Não converte kg/g automaticamente.
create or replace function public.register_production(p_recipe_id uuid,p_product_id uuid,p_quantity numeric,p_manual_total_cost numeric default null,p_notes text default null) returns uuid language plpgsql security invoker as $$ declare o uuid:=auth.uid(); pid uuid; rec record; ing record; total numeric:=0; used numeric; line numeric; begin if o is null or p_quantity<=0 then raise exception 'Autenticação ou quantidade inválida'; end if; if p_recipe_id is not null then select * into rec from recipes where id=p_recipe_id and owner_id=o and finished_product_id=p_product_id; if not found then raise exception 'Receita não encontrada'; end if; for ing in select ri.*,p.average_cost,p.stock_quantity,p.name from recipe_ingredients ri join products p on p.id=ri.ingredient_product_id where ri.recipe_id=p_recipe_id and ri.owner_id=o for update of p loop used:=ing.quantity*(p_quantity/rec.yield_quantity); if ing.stock_quantity<used then raise exception 'Estoque insuficiente: %',ing.name; end if; line:=used*ing.average_cost; total:=total+line; update products set stock_quantity=stock_quantity-used where id=ing.ingredient_product_id; end loop; else if p_manual_total_cost is null or p_manual_total_cost<0 then raise exception 'Informe custo manual'; end if; total:=p_manual_total_cost; end if; insert into productions(owner_id,recipe_id,produced_product_id,produced_quantity,total_cost,unit_cost,notes) values(o,p_recipe_id,p_product_id,p_quantity,total,total/p_quantity,p_notes) returning id into pid; if p_recipe_id is not null then for ing in select ri.*,p.average_cost from recipe_ingredients ri join products p on p.id=ri.ingredient_product_id where ri.recipe_id=p_recipe_id and ri.owner_id=o loop used:=ing.quantity*(p_quantity/rec.yield_quantity); line:=used*ing.average_cost; insert into production_items(owner_id,production_id,ingredient_product_id,quantity_used,unit_cost_snapshot,line_cost) values(o,pid,ing.ingredient_product_id,used,ing.average_cost,line); insert into stock_movements(owner_id,product_id,movement_type,quantity_delta,unit_cost,reference_type,reference_id) values(o,ing.ingredient_product_id,'production_input',-used,ing.average_cost,'production',pid); end loop; end if; update products set stock_quantity=stock_quantity+p_quantity,average_cost=((stock_quantity*average_cost)+total)/(stock_quantity+p_quantity) where id=p_product_id and owner_id=o; insert into stock_movements(owner_id,product_id,movement_type,quantity_delta,unit_cost,reference_type,reference_id) values(o,p_product_id,'production_output',p_quantity,total/p_quantity,'production',pid); return pid; end $$;
-- Venda: valida todo o carrinho, baixa estoque, grava snapshots de custo e recebível/caixa atomicamente.
create or replace function public.register_sale(p_customer_id uuid,p_payment_method text,p_discount numeric,p_items jsonb,p_notes text default null) returns uuid language plpgsql security invoker as $$ declare o uuid:=auth.uid(); sid uuid; it jsonb; p products%rowtype; q numeric; price numeric; sub numeric:=0; tot numeric; stat text; begin if o is null then raise exception 'Autenticação necessária'; end if; if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Carrinho vazio'; end if; if p_payment_method not in('cash','pix','debit','credit','on_account') then raise exception 'Pagamento inválido'; end if; for it in select * from jsonb_array_elements(p_items) loop q:=(it->>'quantity')::numeric; price:=(it->>'unit_price')::numeric; select * into p from products where id=(it->>'product_id')::uuid and owner_id=o and product_type='cake' for update; if not found or q<=0 or price<0 then raise exception 'Item inválido'; end if; if p.stock_quantity<q then raise exception 'Estoque insuficiente: %',p.name; end if; sub:=sub+q*price; end loop; if p_discount<0 or p_discount>sub then raise exception 'Desconto inválido'; end if; tot:=round(sub-p_discount,2); stat:=case when p_payment_method='on_account' then 'pending' else 'paid' end; insert into sales(owner_id,customer_id,subtotal,discount,total,payment_method,payment_status,notes) values(o,p_customer_id,sub,p_discount,tot,p_payment_method,stat,p_notes) returning id into sid; for it in select * from jsonb_array_elements(p_items) loop q:=(it->>'quantity')::numeric;price:=(it->>'unit_price')::numeric;select * into p from products where id=(it->>'product_id')::uuid and owner_id=o for update;update products set stock_quantity=stock_quantity-q where id=p.id;insert into sale_items(owner_id,sale_id,product_id,product_name_snapshot,quantity,unit_price,unit_cost_snapshot,line_total) values(o,sid,p.id,p.name,q,price,p.average_cost,q*price);insert into stock_movements(owner_id,product_id,movement_type,quantity_delta,unit_cost,reference_type,reference_id) values(o,p.id,'sale',-q,p.average_cost,'sale',sid);end loop; if stat='pending' then insert into accounts_receivable(owner_id,description,customer_id,sale_id,amount,status) values(o,'Venda a prazo',p_customer_id,sid,tot,'pending'); else insert into cash_movements(owner_id,movement_type,amount,description,reference_type,reference_id) values(o,'sale',tot,'Recebimento de venda','sale',sid); end if;return sid;end $$;
grant execute on function public.register_purchase(uuid,uuid,numeric,numeric,text,text) to authenticated;grant execute on function public.register_production(uuid,uuid,numeric,numeric,text) to authenticated;grant execute on function public.register_sale(uuid,text,numeric,jsonb,text) to authenticated;
